// Nagłówek VAPID (RFC 8292): JWT ES256 z aud = origin usługi push. Podpis robi węzeł Crypto.
const b64u = (s) => Buffer.from(s).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
return $input.all().filter((it) => it.json.endpoint).map((it) => {
  const aud = (it.json.endpoint.match(/^https:\/\/[^/]+/) || [''])[0];
  const header = b64u(JSON.stringify({ typ: 'JWT', alg: 'ES256' }));
  const payload = b64u(JSON.stringify({ aud, exp: Math.floor(Date.now() / 1000) + 3600, sub: 'mailto:admin@example.com' }));
  return { json: { endpoint: it.json.endpoint, unsigned: header + '.' + payload } };
});

// Crypto node zwraca podpis ECDSA w DER, JWT wymaga surowego r||s (64 bajty).
const VAPID_PUB = 'REPLACE_WITH_VAPID_PUBLIC_KEY';
const b64u = (buf) => buf.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
function derToRaw(der) {
  let o = 2;
  if (der[1] & 0x80) o += der[1] & 0x7f;
  const int = () => {
    if (der[o] !== 0x02) throw new Error('Zły DER');
    const len = der[o + 1];
    let v = der.slice(o + 2, o + 2 + len);
    o += 2 + len;
    while (v.length > 32 && v[0] === 0) v = v.slice(1);
    return Buffer.concat([Buffer.alloc(32 - v.length), v]);
  };
  return Buffer.concat([int(), int()]);
}
return $input.all().map((it) => ({ json: { endpoint: it.json.endpoint,
  authorization: `vapid t=${it.json.unsigned + '.' + b64u(derToRaw(Buffer.from(it.json.sig, 'base64')))}, k=${VAPID_PUB}` } }));

// 201 = OK, 404/410 = subskrypcja martwa (kasujemy), reszta = błąd.
const subs = $('Złóż nagłówek VAPID').all();
return $input.all().map((it, i) => ({ json: { endpoint: subs[i].json.endpoint,
  status: Number(it.json.statusCode ?? it.json.error?.status ?? it.json.error?.httpCode ?? 0) || 0 } }));
